From 00de003228040a17880cc07fec97a6ff6a78846b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 23:51:12 +0100
Subject: [PATCH] components/timezoneselector: show time zone abbreviations in
 the list
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

The time zone combobox only listed city names, so people who know a zone
by its code (PST, JST, CET…) had to guess which city it belongs to. Each
entry now also shows the zone's current abbreviation, like "Tokyo (JST)".

BUG: 440881
---
 .../timezoneselector/TimezoneSelector.qml     | 26 ++++++++++++++-----
 components/timezoneselector/timezoneutils.cpp |  6 +++++
 components/timezoneselector/timezoneutils.h   |  1 +
 3 files changed, 27 insertions(+), 6 deletions(-)

diff --git a/components/timezoneselector/TimezoneSelector.qml b/components/timezoneselector/TimezoneSelector.qml
index bf8d12bda6..798423e988 100644
--- a/components/timezoneselector/TimezoneSelector.qml
+++ b/components/timezoneselector/TimezoneSelector.qml
@@ -133,6 +133,16 @@ Item {
         let i = id.indexOf("/")
         return [root.understandable(id.slice(0, i)), root.understandable(id.slice(i + 1))]
     }
+    // Locations of a region with the current abbreviation of their time zone, e.g. "Tokyo (JST)"
+    function locationsOf(region: string): var {
+        return (root.areasByRegion[region] ?? []).map(location => {
+            const abbreviation = Workspace.TimeZoneUtils.abbreviation(root.technical(region) + '/' + root.technical(location))
+            const text = abbreviation && abbreviation !== location
+                ? i18ndc("plasmashellprivateplugin", "@item:inlistbox time zone location and its abbreviation, e.g. Tokyo (JST)", "%1 (%2)", location, abbreviation)
+                : location
+            return { text, value: location }
+        })
+    }

     Kirigami.InlineMessage {
         position: Kirigami.InlineMessage.Header
@@ -185,19 +195,21 @@ Item {
             id: mobileLocationComboBox

             visible: mobileRegionComboBox.currentText !== mobileRegionComboBox.chooseText
+            textRole: "text"
+            valueRole: "value"
             text: i18ndc("plasmashellprivateplugin", "@label:listbox In the context of time zone selection", "Time zone:")

             Connections {
                 target: root
                 function onSelectedTimeZoneChanged() {
                     let [prefix, suffix] = root.split(root.selectedTimeZone)
-                    mobileLocationComboBox.model = root.areasByRegion[prefix]
-                    mobileLocationComboBox.currentIndex = mobileLocationComboBox.model.indexOf(suffix)
+                    mobileLocationComboBox.model = root.locationsOf(prefix)
+                    mobileLocationComboBox.currentIndex = mobileLocationComboBox.indexOfValue(suffix)
                 }
             }

             onActivated: {
-                root.selectedTimeZone = root.technical(mobileRegionComboBox.currentText) + '/' + root.technical(mobileLocationComboBox.currentText)
+                root.selectedTimeZone = root.technical(mobileRegionComboBox.currentText) + '/' + root.technical(mobileLocationComboBox.currentValue)
             }
         }
     }
@@ -441,6 +453,8 @@ Item {

                 visible: regionComboBox.currentText !== regionComboBox.chooseText
                 displayText: currentText
+                textRole: "text"
+                valueRole: "value"

                 Accessible.name: i18nd("plasmashellprivateplugin", "Timezone location selector")

@@ -448,13 +462,13 @@ Item {
                     target: root
                     function onSelectedTimeZoneChanged() {
                         let [prefix, suffix] = root.split(root.selectedTimeZone)
-                        locationComboBox.model = root.areasByRegion[prefix]
-                        locationComboBox.currentIndex = locationComboBox.model.indexOf(suffix)
+                        locationComboBox.model = root.locationsOf(prefix)
+                        locationComboBox.currentIndex = locationComboBox.indexOfValue(suffix)
                     }
                 }

                 onActivated: {
-                    root.selectedTimeZone = root.technical(regionComboBox.currentText) + '/' + root.technical(locationComboBox.currentText)
+                    root.selectedTimeZone = root.technical(regionComboBox.currentText) + '/' + root.technical(locationComboBox.currentValue)
                 }
             }
         }
diff --git a/components/timezoneselector/timezoneutils.cpp b/components/timezoneselector/timezoneutils.cpp
index 7369de39f3..05fc9e0bf6 100644
--- a/components/timezoneselector/timezoneutils.cpp
+++ b/components/timezoneselector/timezoneutils.cpp
@@ -2,6 +2,7 @@
 //
 // SPDX-License-Identifier: LGPL-2.0-or-later

+#include <QDateTime>
 #include <QTimeZone>

 #include "timezoneutils.h"
@@ -11,4 +12,9 @@ QList<QByteArray> TimeZoneUtils::availableTimeZoneIds() const
     return QTimeZone::availableTimeZoneIds();
 }

+QString TimeZoneUtils::abbreviation(const QString &timeZoneId) const
+{
+    return QTimeZone(timeZoneId.toUtf8()).abbreviation(QDateTime::currentDateTime());
+}
+
 #include "moc_timezoneutils.cpp"
diff --git a/components/timezoneselector/timezoneutils.h b/components/timezoneselector/timezoneutils.h
index 7b04eb0bbf..fe8c5b2217 100644
--- a/components/timezoneselector/timezoneutils.h
+++ b/components/timezoneselector/timezoneutils.h
@@ -16,4 +16,5 @@ class TimeZoneUtils : public QObject

 public:
     Q_INVOKABLE QList<QByteArray> availableTimeZoneIds() const;
+    Q_INVOKABLE QString abbreviation(const QString &timeZoneId) const;
 };
-- 
2.53.0
